classdef TestV04GoldenRegression < matlab.unittest.TestCase
    % Independent rack-zero references generated by MATLAB R2025b from:
    % v0.4.0 commit 6cf64c5c0a23d4c4deb396681a8dfdf2d2f4443d.
    % Values were produced with the historical solveBump implementation,
    % before solveCornerPath existed. Each row stores, in order:
    % UBJ, LBJ, TIE_ROD_OUTBOARD, WHEEL_CENTER, wheelAxis, camber, toe.

    properties
        OriginalPath
    end

    methods (TestMethodSetup)
        function addSourceToPath(testCase)
            root = fileparts(fileparts(mfilename("fullpath")));
            testCase.OriginalPath = path;
            testCase.addTeardown(@() path(testCase.OriginalPath));
            addpath(fullfile(root, "src"));
        end
    end

    methods (Test)
        function analyticFlAndMirroredFrMatchV04(testCase)
            steering = fsd.model.createSteeringSystem( ...
                analyticAxleFixture(false), 1.6, "m");
            zero = fsd.kinematics.solveSteering(steering, 0, 0, "mm");
            bump = fsd.kinematics.solveSteering(steering, 0, 20, "mm");
            rebound = fsd.kinematics.solveSteering( ...
                steering, 0, -20, "mm");

            flZero = [0, -0.6, 5/12, 0, -0.6, 1/12, ...
                0.05, -0.57, 0.23, 0, -0.65, 0.25, ...
                0, -1, 0, 0, 0];
            flBump = [1.9081958235744878e-17, ...
                -0.59304054448988142, 0.43473365699351457, ...
                -9.1072982488782372e-18, -0.60519260336592751, ...
                0.10162190611074517, 0.050747285623706201, ...
                -0.57114697075195486, 0.24714413469748547, ...
                -0.0012724665978282171, -0.64906715299047046, 0.27, ...
                -0.025449331956564424, -0.99901158125131939, ...
                0.036444368957402627, -0.036464256825650805, ...
                0.02546900301831885];
            flRebound = [-2.3418766925686896e-17, ...
                -0.6051926089365991, 0.39837807026160038, ...
                4.3368086899420177e-18, -0.59304053436995363, ...
                0.065266319951231055, 0.049203186777301823, ...
                -0.56711852965388354, 0.21297619502249743, ...
                0.0012998568157925111, -0.6490664463002922, 0.23, ...
                0.025997136315850388, -0.99899749294031615, ...
                -0.036443902128314117, 0.036464303928760058, ...
                -0.026017352787515949];
            frBump = [-3.2526065174565133e-18, ...
                0.5930405444898813, 0.43473365699351457, ...
                3.187554387107383e-17, 0.60519260336592762, ...
                0.10162190611074517, 0.050747285623706215, ...
                0.57114697075195486, 0.24714413469748547, ...
                -0.0012724665978282158, 0.64906715299047046, 0.27, ...
                -0.025449331956564583, 0.99901158125131939, ...
                0.036444368957403009, -0.036464256825651187, ...
                0.02546900301831901];
            frRebound = [-3.0357660829594124e-18, ...
                0.6051926089365991, 0.39837807026160038, ...
                1.0408340855860843e-17, 0.59304053436995385, ...
                0.065266319951231055, 0.04920318677730183, ...
                0.56711852965388365, 0.2129761950224974, ...
                0.0012998568157925451, 0.64906644630029231, 0.23, ...
                0.025997136315850804, 0.99899749294031615, ...
                -0.036443902128313936, 0.036464303928759878, ...
                -0.026017352787516365];

            testCase.verifyGolden(zero.leftResult, flZero);
            testCase.verifyGolden(bump.leftResult, flBump);
            testCase.verifyGolden(rebound.leftResult, flRebound);
            testCase.verifyGolden(bump.rightResult, frBump);
            testCase.verifyGolden(rebound.rightResult, frRebound);
        end

        function nontrivialThreeDimensionalGeometryMatchesV04(testCase)
            left = threeDimensionalCornerFixture();
            axle = fsd.model.createAxleGeometry(left, ...
                fsd.geometry.reflectDoubleWishboneGeometry(left));
            steering = fsd.model.createSteeringSystem(axle, 1.6, "m");
            result = fsd.kinematics.solveSteering( ...
                steering, 0, 12, "mm");
            expected = [0.031734444260060626, ...
                -0.59567601630277356, 0.43043091946621403, ...
                -0.021245219553871889, -0.60335081558307602, ...
                0.090969209286450498, 0.050553637698901505, ...
                -0.57077596263335251, 0.23957541054501091, ...
                -0.00057554605697163956, -0.64940766334135802, 0.262, ...
                -0.016420513893731059, -0.99954853670177746, ...
                0.025161269856694521, -0.025167319421219202, ...
                0.016426452901017508];
            testCase.verifyGolden(result.leftResult, expected);
        end
    end

    methods (Access = private)
        function verifyGolden(testCase, result, expected)
            testCase.assertTrue(result.converged, result.failureReason);
            toe_rad = fsd.analysis.toeFromWheelAxis( ...
                result.wheelAxis, result.cornerId);
            actual = [result.state.ubj_m, result.state.lbj_m, ...
                result.state.tieRodOutboard_m, result.state.wheelCenter_m, ...
                result.wheelAxis, result.camber_rad, toe_rad];
            testCase.verifyEqual(actual, expected, "AbsTol", 2e-10);
        end
    end
end
